from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
drive_motor_left = Motor(Port.B, Direction.COUNTERCLOCKWISE)
drive_motor_right = Motor(Port.F, Direction.CLOCKWISE)
Attach_motor_left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Attach_motor_right = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(drive_motor_left, drive_motor_right, 54, 114)


# The main program starts here.
drive_base.settings(straight_speed=350)
drive_base.straight(550)
drive_base.settings(turn_rate=40)
drive_base.turn(70)
drive_base.straight(370)
drive_base.turn(-68)
Attach_motor_left.run_angle(40, -60)
drive_base.settings(straight_speed=100)
drive_base.straight(70)
Attach_motor_left.run_angle(40, -75)
drive_base.straight(-25)
Attach_motor_left.run_angle(60, 90)
drive_base.straight(-50)
